using DomainConsole.Shared;
using System.Windows;
using System.Windows.Controls;
namespace DomainConsole;
public sealed class RebootPlan {public string RequestedUtc {get;set;}="";public string DueUtc {get;set;}="";public string BeforeBootUtc {get;set;}="";}
public sealed class PostRebootSettings {public int ProbeSeconds {get;set;}=60;public int SettleSeconds {get;set;}=120;public bool Scan {get;set;}}
public partial class MainWindow {
 PostRebootSettings postReboot=Store.Read("post-reboot-settings.json",new PostRebootSettings());
 void RegisterRebootPlan(RemoteJob? job,ComputerRow row,PollResult data){if(job==null)return;if(data.RebootPlan==null)return;bool header=job.Name=="Перезагрузка текущего компьютера";if(!header&&data.State?.Status!="RebootScheduled")return;
  if(!rebootWatches.TryGetValue(row.Host,out var watch)||watch.JobId!=job.Id){if(rebootWatches.TryGetValue(row.Host,out var existing)&&existing.JobId!=job.Id&&DateTimeOffset.TryParse(existing.RequestedUtc,out var newer)&&DateTimeOffset.TryParse(data.RebootPlan.RequestedUtc,out var older)&&newer>older)return;WatchReboot(job,row.Host,0);watch=rebootWatches[row.Host];}
  if(watch.Confirmed)return;var plan=data.RebootPlan;if(!DateTimeOffset.TryParse(plan.RequestedUtc,out _)||!DateTimeOffset.TryParse(plan.DueUtc,out var due)||!DateTimeOffset.TryParse(data.ClientUtc,out var now))return;
  watch.RequestedUtc=plan.RequestedUtc;watch.BeforeBootUtc=plan.BeforeBootUtc;watch.ExpectedUtc=DateTimeOffset.UtcNow.AddSeconds(Math.Max(0,(due-now).TotalSeconds));watch.Confirmed=true;watch.Scan=job.ScanAfterReboot;watch.Phase="Ожидается назначенная перезагрузка";watch.Next=watch.ExpectedUtc.AddSeconds(Math.Max(15,postReboot.ProbeSeconds));watch.Until=watch.ExpectedUtc.AddDays(2);Store.Write("reboot-watches.json",rebootWatches);
 }
 string PostRebootText(string host){if(!rebootWatches.TryGetValue(host,out var w)||w.Done)return "";if(!w.Confirmed)return "Ожидается подтверждение назначения перезагрузки на клиенте";return w.Phase+(w.ExpectedUtc>DateTimeOffset.UtcNow?" · через "+Age(w.ExpectedUtc-DateTimeOffset.UtcNow):"")+(w.LastError.Length>0?" · "+w.LastError:"");}
 async Task ContinueAfterReboot(string host,RebootWatch watch,TargetRecord target){if(watch.FollowupId.Length>0&&History.Any(j=>j.Id==watch.FollowupId)){EnsureFollowupJob(host,watch,target);return;}if(!watch.Scan){watch.Phase="Возврат подтверждён; статус обновлён";watch.Done=true;return;}if(rebootSnapshots.GetValueOrDefault(host)?.Required!=false){watch.LastError="Повторное требование перезагрузки или неполная проверка; поиск отложен";return;}
  if(History.Any(j=>IsWsusJob(j)&&j.Targets.Any(t=>t.Host.Equals(host,StringComparison.OrdinalIgnoreCase)&&(t.Status is "Queued" or "Sending" or "Submitted" or "Running")))){watch.LastError="Есть активное задание WSUS; поиск отложен";return;}
  var live=await remote.LiveUpdates(target);if(live.InstallerBusy||live.InstallationEvidence.Length>0||live.Limitation.Length>0){watch.LastError="Клиент ещё занят либо его готовность не подтверждена; поиск отложен";return;}
  EnsureFollowupJob(host,watch,target);
 }
 void EnsureFollowupJob(string host,RebootWatch watch,TargetRecord target){if(watch.FollowupId.Length==0){watch.FollowupId=Guid.NewGuid().ToString();Store.Write("reboot-watches.json",rebootWatches);}var job=History.FirstOrDefault(j=>j.Id==watch.FollowupId);if(job==null){var t=Store.Clone(target);t.Status="Queued";t.State=null;t.Output="";job=new(){Id=watch.FollowupId,Name="После перезагрузки: проверка обновлений",OutputChannel="WSUS",Targets=new(){t},Steps=new(){new(){Kind="UpdateScan",Name="WSUS · поиск после перезагрузки"}}};History.Insert(0,job);Save();}foreach(var t in job.Targets.Where(t=>t.Status=="Queued"&&t.State==null))if(!queue.Any(q=>q.Job.Id==job.Id&&q.Target.Host==t.Host))queue.Enqueue((job,t));watch.Done=true;watch.Phase="После перезагрузки создано задание поиска";watch.LastError="";}
 void RestoreFollowupQueues(){foreach(var entry in rebootWatches.Where(x=>x.Value.FollowupId.Length>0)){var job=History.FirstOrDefault(j=>j.Id==entry.Value.FollowupId);if(job!=null)foreach(var t in job.Targets.Where(t=>t.Status=="Queued"&&t.State==null))if(!queue.Any(q=>q.Job.Id==job.Id&&q.Target.Host==t.Host))queue.Enqueue((job,t));}}

 async Task MonitorReboots(){if(checkingReboots||closing)return;checkingReboots=true;try{foreach(var entry in rebootWatches.Where(x=>!x.Value.Done&&x.Value.Next<=DateTimeOffset.UtcNow).Take(2).ToList()){
  var host=entry.Key;var watch=entry.Value;var job=History.FirstOrDefault(j=>j.Id==watch.JobId);var target=job?.Targets.FirstOrDefault(t=>t.Host.Equals(host,StringComparison.OrdinalIgnoreCase));watch.Next=DateTimeOffset.UtcNow.AddSeconds(Math.Clamp(postReboot.ProbeSeconds,30,600));
  if(target==null||target.Status=="Cancelled"){watch.Done=true;watch.Phase="Наблюдение отменено";continue;}
  if(DateTimeOffset.UtcNow>watch.Until){watch.Done=true;watch.Phase="Ожидание возврата/продолжения завершено по сроку";continue;}
  if(!watch.Confirmed&&target.State!=null&&target.State.SchemaVersion<28&&DateTimeOffset.TryParse(target.State.Started,out var legacyStart)){watch.Confirmed=true;watch.RequestedUtc=legacyStart.ToString("o");watch.Scan=false;watch.Phase="Прежнее наблюдение: только проверка возврата";}
  if(!watch.Confirmed){if(target.Status is "Failed" or "ConnectionFailed"){watch.Done=true;watch.Phase="Назначение перезагрузки не подтверждено";}continue;}
  try{var snapshot=await remote.ReadRebootState(target);ConnectionSucceeded(host);ApplyClientSnapshot(host,snapshot);
   if(!RebootReturned(watch,snapshot)){watch.LastError="Новая загрузка Windows ещё не подтверждена";continue;}
   if(watch.ReadyAfter==default){watch.ReadyAfter=DateTimeOffset.UtcNow.AddSeconds(Math.Clamp(postReboot.SettleSeconds,0,1800));watch.Phase="Перезагрузка подтверждена; ожидание готовности служб";watch.Next=watch.ReadyAfter;watch.LastError="";continue;}
   if(DateTimeOffset.UtcNow<watch.ReadyAfter)continue;
   try{var settings=ReadWsus();var reply=(await remote.WsusOverview(settings,new(){host},CancellationToken.None)).SingleOrDefault();if(reply?.Found==true&&reply.Report!=null&&reply.Error.Length==0){var started=reportCache.GetValueOrDefault(host)?.Started??"";SaveReportCache(host,reply.Report,settings.Host+":"+settings.Port,started,false);serverReports[host]=reply.Report.Format(settings.Host+":"+settings.Port,started);}}catch(Exception ex){overviewErrors[host]=ex.Message;}
   watch.Phase="Возврат подтверждён; проверка готовности";await ContinueAfterReboot(host,watch,target);
  }catch(Exception ex){ConnectionFailed(host,ex.Message);watch.LastError=ShortConnectionError(ex.Message);}
  finally{Store.Write("reboot-watches.json",rebootWatches);RefreshOutcomes();if(CurrentHost(host))ShowCurrent();}
 }}finally{Store.Write("reboot-watches.json",rebootWatches);checkingReboots=false;await SendQueue();}}
 void SavePostReboot_Click(object sender,RoutedEventArgs e)=>Guard(()=>{if(!int.TryParse(RebootProbeSeconds.Text,out var probe)||probe<30||probe>600||!int.TryParse(RebootSettleSeconds.Text,out var settle)||settle<0||settle>1800)throw new Exception("Период: 30–600 секунд; готовность: 0–1800 секунд.");postReboot=new(){ProbeSeconds=probe,SettleSeconds=settle,Scan=PostRebootScan.IsChecked==true};Store.Write("post-reboot-settings.json",postReboot);Notify("Параметры наблюдения сохранены. Уже назначенные действия поиска не меняются.");});
 void PostRebootInfo_Click(object sender,RoutedEventArgs e){var row=Current();if(!rebootWatches.TryGetValue(row.Host,out var watch)){Notify("Наблюдение за перезагрузкой этого ПК не назначено.");return;}var window=new Window{Owner=this,Title="После перезагрузки · "+row.Name,Width=500,SizeToContent=SizeToContent.Height,WindowStartupLocation=WindowStartupLocation.CenterOwner};var panel=new StackPanel{Margin=new(16)};panel.Children.Add(new TextBlock{Text=PostRebootText(row.Host)+"\nПоиск после возврата: "+(watch.Scan?"включён":"выключен"),TextWrapping=TextWrapping.Wrap});var stop=new Button{Content="Прекратить наблюдение и продолжение"};stop.Click+=(s,a)=>{watch.Done=true;watch.Phase="Наблюдение остановлено пользователем";Store.Write("reboot-watches.json",rebootWatches);window.Close();};panel.Children.Add(stop);panel.Children.Add(new TextBlock{Text="Это не отменяет перезагрузку и не останавливает уже созданное задание поиска. Для них используйте соответствующие кнопки отмены.",TextWrapping=TextWrapping.Wrap});window.Content=panel;window.ShowDialog();}
}
